12	  const dateFilter = filters.find((f) => f.factor === "displayTime");
13	  if (!dateFilter) return undefined;
14	  const match = DATE_RE.exec(dateFilter.value);
15	  if (!match) return undefined;
16	  const year = Number(match[1]);
17	  const month = Number(match[2]);
18	  const day = Number(match[3]);
19	  // Construct a local-time Date and verify the components round-trip
20	  // (catches things like 2025-13-40 that JS would silently roll forward).
21	  const candidate = new Date(year, month - 1, day, now.getHours(), now.getMinutes(), now.getSeconds());
22	  if (candidate.getFullYear() !== year || candidate.getMonth() !== month - 1 || candidate.getDate() !== day) {
23	    return undefined;
24	  }
25	  return candidate;
